DIGITS = "0123456789abcdefghijklmnopqrstuvwxyz"


def _check_base(base):
    if not isinstance(base, int) or isinstance(base, bool) or not 2 <= base <= 36:
        raise ValueError(f"base must be an int from 2 to 36, got {base!r}")


def to_base(number, base):
    """Return the int `number` written in `base` (2-36), lower-case digits.

    Zero is "0"; a negative number gets a leading "-".
    """
    _check_base(base)
    if not isinstance(number, int) or isinstance(number, bool):
        raise TypeError(f"number must be an int, got {type(number).__name__}")
    if number == 0:
        return "0"
    sign = "-" if number < 0 else ""
    n = abs(number)
    out = []
    while n:
        n, r = divmod(n, base)
        out.append(DIGITS[r])
    return sign + "".join(reversed(out))


def from_base(text, base):
    """Parse `text` written in `base` (2-36) back into an int.

    Accepts upper- or lower-case digits and one optional leading "-".
    Raises ValueError for an empty string, a lone "-", any digit not valid
    in the base, or any other character (spaces included).
    """
    _check_base(base)
    if not isinstance(text, str):
        raise TypeError(f"text must be a str, got {type(text).__name__}")
    body = text
    negative = False
    if body.startswith("-"):
        negative = True
        body = body[1:]
    if not body:
        raise ValueError(f"no digits in {text!r}")
    value = 0
    for ch in body:
        # Map ASCII letters explicitly; str.lower() would also fold some
        # non-ASCII characters (e.g. the Kelvin sign) onto ASCII letters.
        if "A" <= ch <= "Z":
            code = ch.lower()
        else:
            code = ch
        idx = DIGITS.find(code) if len(code) == 1 and code.isascii() else -1
        if idx < 0 or idx >= base:
            raise ValueError(f"invalid digit {ch!r} for base {base} in {text!r}")
        value = value * base + idx
    return -value if negative else value
